#[test]
fn traces_kotlin_cross_file_qualified_receiver_calls_via_local_constructor_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let caller_path = dir.join("Holder.kt");
    let base_path = dir.join("Other.kt");
    let db_path = dir.join("symbols.db");
    fs::write(&caller_path, "package com.example\n\nimport org.util.Other\n\nclass Holder {\n    fun run(): Int {\n        val other = Other()\n        return other.helper(1)\n    }\n}\n").unwrap();
    fs::write(
        &base_path,
        "package org.util\n\nclass Other {\n    fun helper(value: Int): Int = value\n}\n",
    )
    .unwrap();

    // A local binding initialized from a qualified constructor call pins the
    // receiver to the imported constructed type, so the trailing member
    // dispatches across packages.
    let helper_path = "org::util::Other::helper";
    let live = trace_symbol_graph(&dir, helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.indexed_files, 2);
    assert_eq!(live.symbol.symbol_id, helper_path);
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::Holder::run");

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 1);
    assert_eq!(persisted.callers[0].symbol_id, "com::example::Holder::run");
}

