#[test]
fn traces_kotlin_cross_file_interface_property_chain_receiver_calls_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let caller_path = dir.join("Caller.kt");
    let base_path = dir.join("Base.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &caller_path,
        "package com.example\n\nimport org.util.Group\n\nfun caller(): Int {\n    val group = Group()\n    return group.renderer.render(1)\n}\n\nfun secondCaller(): Int {\n    val group = Group()\n    return group.renderer.render(2)\n}\n",
    )
    .unwrap();
    fs::write(
        &base_path,
        "package org.util\n\ninterface Renderer {\n    fun render(value: Int): Int = value\n}\nclass Screen : Renderer\nclass Group {\n    val renderer: Renderer = Screen()\n}\n",
    )
    .unwrap();

    // A property hop whose declared type is an interface declared in an
    // explicitly imported package pins the trailing member on the imported
    // interface, so `group.renderer.render(...)` dispatches across packages.
    let render_path = "org::util::Renderer::render";
    let live = trace_symbol_graph(&dir, render_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.indexed_files, 2);
    assert_eq!(live.symbol.symbol_id, render_path);
    assert_eq!(live.callers.len(), 2);
    assert!(
        live.callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::caller")
    );
    assert!(
        live.callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::secondCaller")
    );

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, render_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.indexed_files, 2);
    assert_eq!(persisted.callers.len(), 2);
    assert!(
        persisted
            .callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::caller")
    );
    assert!(
        persisted
            .callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::secondCaller")
    );
}

