#[test]
fn traces_kotlin_property_chain_initializer_top_level_array_property_shadowing_fails_closed_in_live_workspace()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Holder {\n    val items: Array<Item> = arrayOf()\n}\n\nval itemGroup: Array<Item> = arrayOf()\n\nclass Util {\n    fun runShadowedLocal(): Int {\n        val itemGroup = Holder()\n        val first = itemGroup[0]\n        return first.helper(1)\n    }\n    fun runBoundNonArrayBase(): Int {\n        val holder = Holder()\n        val first = holder[0]\n        return first.helper(2)\n    }\n    fun control(): Int {\n        val first = itemGroup\n        return first[0].helper(3)\n    }\n}\n\nclass MemberShadow {\n    val itemGroup: Int = 0\n    fun runShadowedMember(): Int {\n        val first = itemGroup[0]\n        return first.helper(4)\n    }\n}\n",
    )
    .unwrap();

    // A locally bound non-array value or an enclosing member property shadows
    // the same-named top-level array property (Kotlin scope: local, then
    // member, then package), so element access on those bases fails closed;
    // only the unshadowed control caller dispatches on the top-level
    // property's element component type.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::Util::control");
}

#[test]
fn traces_kotlin_property_chain_initializer_bound_array_roots_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Holder {\n    val item: Item = Item()\n    val items: Array<Item> = arrayOf()\n}\n\nval itemGroup: Array<Item> = arrayOf()\n\nopen class Base {\n    val inherited: Array<Item> = arrayOf()\n}\n\nclass MemberHost : Base() {\n    val own: Array<Item> = arrayOf()\n    fun runOwnMember(): Int {\n        val first = own\n        return first[0].helper(1)\n    }\n    fun runInheritedMember(): Int {\n        val first = inherited\n        return first[0].helper(2)\n    }\n    fun runParameter(items: Array<Item>): Int {\n        val first = items\n        return first[0].helper(3)\n    }\n    fun runLocalExplicit(): Int {\n        val local: Array<Item> = arrayOf()\n        val first = local\n        return first[0].helper(4)\n    }\n    fun runBoundChain(): Int {\n        val group = itemGroup\n        val first = group\n        return first[0].helper(5)\n    }\n    fun runElementAccessBase(): Int {\n        val holder = Holder()\n        val first = holder.items[0]\n        return first.helper(6)\n    }\n    fun runReboundElementAccessBase(): Int {\n        val holder = Holder()\n        val x = holder.items[0]\n        val first = x\n        return first.helper(7)\n    }\n    fun failNonArrayChain(): Int {\n        val holder = Holder()\n        val first = holder.item\n        return first[0].helper(8)\n    }\n}\n",
    )
    .unwrap();

    // A single-hop array terminal also resolves when the terminal name is
    // bound directly: an own or inherited member property (`val first = own`,
    // `val first = inherited`), a parameter or explicitly typed local
    // (`val first = items`, `val first = local`), a name bound from another
    // chain (`val group = itemGroup` then `val first = group`), and a name
    // bound from an element-access base, direct or re-bound
    // (`val first = holder.items[0]` or `val x = holder.items[0]` then
    // `val first = x`). Element access on a bound non-array chain
    // (`val first = holder.item` then `first[0]`) fails closed, so only the
    // seven array-rooted callers dispatch on `Item::helper`.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 7);
    for caller in [
        "com::example::MemberHost::runOwnMember",
        "com::example::MemberHost::runInheritedMember",
        "com::example::MemberHost::runParameter",
        "com::example::MemberHost::runLocalExplicit",
        "com::example::MemberHost::runBoundChain",
        "com::example::MemberHost::runElementAccessBase",
        "com::example::MemberHost::runReboundElementAccessBase",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 7);
    for caller in [
        "com::example::MemberHost::runOwnMember",
        "com::example::MemberHost::runInheritedMember",
        "com::example::MemberHost::runParameter",
        "com::example::MemberHost::runLocalExplicit",
        "com::example::MemberHost::runBoundChain",
        "com::example::MemberHost::runElementAccessBase",
        "com::example::MemberHost::runReboundElementAccessBase",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
}

#[test]
fn traces_kotlin_property_chain_initializer_factory_array_roots_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Maker {\n    fun make(): Array<Item> = arrayOf()\n}\n\nclass Holder {\n    val maker: Maker = Maker()\n    fun make(): Array<Item> = arrayOf()\n}\n\nclass Factory {\n    fun make(): Array<Item> = arrayOf()\n}\n\nobject Registry {\n    val factory: Factory = Factory()\n}\n\nclass NonArrayMaker {\n    fun make(): Item = Item()\n}\n\nclass Util {\n    fun makeItems(): Array<Item> = arrayOf()\n    fun runLocalFactory(): Int {\n        val x = makeItems()\n        val first = x\n        return first[0].helper(1)\n    }\n    fun runMemberMethod(): Int {\n        val holder = Holder()\n        val x = holder.make()\n        val first = x\n        return first[0].helper(2)\n    }\n    fun runChainMethod(): Int {\n        val h = Holder()\n        val x = h.maker.make()\n        val first = x\n        return first[0].helper(3)\n    }\n    fun runObjectChain(): Int {\n        val x = Registry.factory.make()\n        val first = x\n        return first[0].helper(4)\n    }\n    fun runDirectChainMethod(): Int {\n        val h = Holder()\n        val x = h.maker.make()\n        return x[0].helper(5)\n    }\n}\n\nclass Util2 {\n    fun runNonArrayFactory(): Int {\n        val maker = NonArrayMaker()\n        val x = maker.make()\n        val first = x\n        return first[0].helper(6)\n    }\n}\n",
    )
    .unwrap();

    // A single-hop array terminal also resolves when the name is bound from a
    // factory or method-call initializer whose declared return type is a
    // single-level array: a bare local factory (`val x = makeItems()`), a
    // bound-receiver method (`val x = holder.make()`), a multi-hop property
    // chain factory (`val x = h.maker.make()`), an object property chain
    // (`val x = Registry.factory.make()`), and the direct (non-re-bound)
    // multi-hop form (`val x = h.maker.make()` then `x[0]`). A factory whose
    // return type is not an array (`maker.make()` returning `Item`) fails
    // closed for element access, so only the five array-rooted callers
    // dispatch on `Item::helper`.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 5);
    for caller in [
        "com::example::Util::runLocalFactory",
        "com::example::Util::runMemberMethod",
        "com::example::Util::runChainMethod",
        "com::example::Util::runObjectChain",
        "com::example::Util::runDirectChainMethod",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 5);
    for caller in [
        "com::example::Util::runLocalFactory",
        "com::example::Util::runMemberMethod",
        "com::example::Util::runChainMethod",
        "com::example::Util::runObjectChain",
        "com::example::Util::runDirectChainMethod",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
}

