#[test]
fn traces_kotlin_implicit_companion_function_receiver_calls_in_live_workspace_and_persisted_index()
{
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Item {\n    fun helper(value: Int): Int = value\n}\n\nclass Helper {\n    fun inner(): Item = Item()\n}\n\nclass Util {\n    companion object {\n        fun make(): Item = Item()\n        fun makeItems(): Array<Item> = arrayOf()\n        fun makeNullableItems(): Array<Item>? = arrayOf()\n        fun makeNullableGroups(): Array<Helper>? = arrayOf()\n    }\n    fun runCall(): Int {\n        return make().helper(1)\n    }\n    fun runArray(): Int {\n        return makeItems()[0].helper(2)\n    }\n    fun runNullableArray(): Int {\n        return makeNullableItems()!![0].helper(3)\n    }\n    fun runNullableHop(): Int {\n        return makeNullableGroups()!![0].inner().helper(4)\n    }\n    fun runVar(): Int {\n        val first = make()\n        return first.helper(5)\n    }\n    fun runVarArray(): Int {\n        val items = makeItems()\n        return items[0].helper(6)\n    }\n}\n\nclass Holder {\n    companion object {\n        fun make(): Item = Item()\n        fun runInCompanion(): Int {\n            return make().helper(7)\n        }\n    }\n}\n",
    )
    .unwrap();

    // An implicit companion member function call inside a type (bare `make()`
    // in `make().helper(...)`, `makeItems()[0].helper(...)`, the nullable
    // force-unwrapped spellings `makeNullableItems()!![0].helper(...)` and
    // `makeNullableGroups()!![0].inner().helper(...)`, and `val` locals such
    // as `val first = make()` or `val items = makeItems()`) dispatches on the
    // companion function's declared return type or array element component
    // type, including from inside the companion object itself, so all seven
    // chains trace to `Item::helper`.
    let item_path = "com::example::Item::helper";
    let live = trace_symbol_graph(&dir, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, item_path);
    assert_eq!(live.callers.len(), 7);
    for caller in [
        "com::example::Util::runCall",
        "com::example::Util::runArray",
        "com::example::Util::runNullableArray",
        "com::example::Util::runNullableHop",
        "com::example::Util::runVar",
        "com::example::Util::runVarArray",
        "com::example::Holder::Companion::runInCompanion",
    ] {
        assert!(
            live.callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing caller {caller}"
        );
    }

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, item_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 7);
    for caller in [
        "com::example::Util::runCall",
        "com::example::Util::runArray",
        "com::example::Util::runNullableArray",
        "com::example::Util::runNullableHop",
        "com::example::Util::runVar",
        "com::example::Util::runVarArray",
        "com::example::Holder::Companion::runInCompanion",
    ] {
        assert!(
            persisted
                .callers
                .iter()
                .any(|candidate| candidate.symbol_id == caller),
            "missing persisted caller {caller}"
        );
    }
}

