#[test]
fn kotlin_cross_file_this_and_super_rooted_hierarchy_member_calls_fail_closed_for_unsupported_references()
 {
    let dir = temporary_dir();
    let caller_path = dir.join("Caller.kt");
    let base_path = dir.join("Hierarchy.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &caller_path,
        "package com.example\n\nimport org.util.Root\n\ninterface A {\n    fun helper(value: Int): Int = value\n}\ninterface B {\n    fun helper(value: Int): Int = value\n}\nclass Competing : A, B {\n    fun run(): Int {\n        return this.helper(1)\n    }\n}\nopen class MissingBase : Missing\nclass Blocked : MissingBase() {\n    fun run(): Int {\n        return this.helper(1)\n    }\n}\nclass NoSuper {\n    fun run(): Int {\n        return super.helper(1)\n    }\n}\nclass Good : Root {\n    fun run(): Int {\n        return this.render(1)\n    }\n}\n",
    )
    .unwrap();
    fs::write(
        &base_path,
        "package org.util\n\ninterface Root {\n    fun render(value: Int): Int = value\n}\n",
    )
    .unwrap();

    // Competing implemented interfaces and an unresolvable superclass chain
    // both fail closed through a `this.`-rooted call, and a `super.`-rooted
    // call in a class without a resolvable superclass fails closed; only the
    // uniquely resolvable `this.`-rooted interface fallback in `Good` traces
    // across packages.
    let helper_path = "com::example::A::helper";
    let live = trace_symbol_graph(&dir, helper_path, TraceDirection::Callers).unwrap();
    assert!(
        live.callers.is_empty(),
        "competing and blocked this-rooted hierarchies must fail closed"
    );

    let render_path = "org::util::Root::render";
    let live = trace_symbol_graph(&dir, render_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.callers.len(), 1);
    assert_eq!(live.callers[0].symbol_id, "com::example::Good::run");

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, helper_path, TraceDirection::Callers).unwrap();
    assert!(
        persisted.callers.is_empty(),
        "competing and blocked this-rooted hierarchies must fail closed"
    );
    let persisted =
        trace_symbol_graph_from_index(&db_path, render_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 1);
    assert_eq!(persisted.callers[0].symbol_id, "com::example::Good::run");
}

#[test]
fn traces_kotlin_member_chain_after_element_hop_receiver_calls_in_live_workspace_and_persisted_index()
 {
    let dir = temporary_dir();
    let source_path = dir.join("Callers.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &source_path,
        "package com.example\n\nclass Helper {\n    fun helper(value: Int): Int = value\n}\n\nclass Group {\n    val item: Helper = Helper()\n    fun inner(): Helper = Helper()\n}\n\nfun makeGroups(): Array<Group> = arrayOf()\n\nclass Holder {\n    val fieldGroups: Array<Group> = arrayOf()\n    fun run(groups: Array<Group>): Int {\n        val local: Array<Group> = arrayOf()\n        return groups[0].item.helper(1) + groups[1].inner().helper(2) + local[0].item.helper(3) + fieldGroups[0].inner().helper(4)\n    }\n}\n\nfun caller(groups: Array<Group>): Int {\n    return groups[0].item.helper(5) + groups[0].inner().helper(6)\n}\n\nfun factoryCaller(): Int {\n    return makeGroups()[0].item.helper(7) + makeGroups()[1].inner().helper(8)\n}\n",
    )
    .unwrap();

    // Member chains after an element hop on a bound array-typed parameter,
    // local, or enclosing-class property such as `groups[0].item.helper(...)`
    // or `groups[0].inner().helper(...)` walk each subsequent property or
    // method-call hop on the element component type, and a factory-call
    // element-access receiver followed by a member chain such as
    // `makeGroups()[0].inner().helper(...)` resolves the leading factory and
    // walks the trailing hops on the factory return array's element component
    // type.
    let helper_path = "com::example::Helper::helper";
    let live = trace_symbol_graph(&dir, helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(live.symbol.symbol_id, helper_path);
    assert_eq!(live.callers.len(), 3);
    assert!(
        live.callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::caller")
    );
    assert!(
        live.callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::Holder::run")
    );
    assert!(
        live.callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::factoryCaller")
    );

    rebuild_symbol_index(&dir, &db_path).unwrap();
    let persisted =
        trace_symbol_graph_from_index(&db_path, helper_path, TraceDirection::Callers).unwrap();
    assert_eq!(persisted.callers.len(), 3);
    assert!(
        persisted
            .callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::caller")
    );
    assert!(
        persisted
            .callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::Holder::run")
    );
    assert!(
        persisted
            .callers
            .iter()
            .any(|caller| caller.symbol_id == "com::example::factoryCaller")
    );
}

