fn traces_kotlin_cross_file_method_hop_receiver_calls_in_live_workspace_and_persisted_index() {
    let dir = temporary_dir();
    let caller_path = dir.join("Caller.kt");
    let base_path = dir.join("Group.kt");
    let db_path = dir.join("symbols.db");
    fs::write(
        &caller_path,
        "package com.example\n\nimport org.util.Entry\nimport org.util.Group\n\nfun makeGroup(): Group = Group()\n\nfun caller(group: Group): Int {\n    return group.inner().entry.helper(1) + group.inner().inner().deeper().helper(2) + makeGroup().inner().entry.helper(3) + Group().inner().entry.helper(4)\n}\n",
    )
    .unwrap();
    fs::write(
        &base_path,
        "package org.util\n\nclass Entry {\n    fun helper(value: Int): Int = value\n}\nclass Group {\n    val entry: Entry = Entry()\n    fun inner(): Group = this\n    fun deeper(): Entry = Entry()\n}\n",
    )
    .unwrap();

    // A method-call hop such as `inner()` in `group.inner().entry.helper(...)`
    // dispatches on the method's declared return type and continues the chain,
    // including double method hops, factory-call roots, and constructed roots
    // over the imported types; the standalone intermediate invocations also
    // trace to their own methods across packages.
    for target in [
        "org::util::Entry::helper",
        "org::util::Group::inner",
        "org::util::Group::deeper",
    ] {
        let live = trace_symbol_graph(&dir, target, TraceDirection::Callers).unwrap();
        assert_eq!(live.indexed_files, 2);
        assert_eq!(live.symbol.symbol_id, target);
        assert_eq!(live.callers.len(), 1);
        assert_eq!(live.callers[0].symbol_id, "com::example::caller");

        rebuild_symbol_index(&dir, &db_path).unwrap();
        let persisted =
            trace_symbol_graph_from_index(&db_path, target, TraceDirection::Callers).unwrap();
        assert_eq!(persisted.indexed_files, 2);
        assert_eq!(persisted.callers.len(), 1);
        assert_eq!(persisted.callers[0].symbol_id, "com::example::caller");
    }
}

